excels.excel:

EXPORT WITH SHEET="应收账款账龄分析表", HEADER=true,
    MAPPING={"a":"客户名称","b":"应收金额","c":"30天内","d":"31-60天","e":"61天以上","f":"逾期金额","g":"逾期占比"},
    FORMAT={"b":"#,##0.00","c":"#,##0.00","d":"#,##0.00","e":"#,##0.00","f":"#,##0.00","g":"0.00%"},
    FORMULAS={
        F2:'D2+E2',G2:'F2/B2',F3:'D3+E3',G3:'F3/B3',F4:'D4+E4',G4:'F4/B4',
        F5:'D5+E5',G5:'F5/B5',F6:'D6+E6',G6:'F6/B6',
        B7:'SUM(B2:B6)',C7:'SUM(C2:C6)',D7:'SUM(D2:D6)',E7:'SUM(E2:E6)',
        F7:'D7+E7',G7:'F7/B7'
    },
    STYLE={
        ROW 7:{bold:true,fillPattern:solid_foreground,fillForegroundColor:lightYellow,alignment:right,verticalAlignment:center},
        G6:{color:red,bold:true}
    }
